void write_and_verify_image(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  gchar *temp_file_path;
  GError *error = NULL;
  GFile *file;
  GimpImage *loaded_image;

  image = create_main_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file_path = g_strdup_printf("/tmp/test_image_%d.xcf", getpid());
  file = g_file_new_for_path(temp_file_path);

  gimp_file_save(GIMP_FILE_SAVE_DIALOG(NULL), NULL, GIMP_FILE_SAVE_OVERWRITE_ASK, image, NULL, "XCF", temp_file_path, &error);
  g_assert(error == NULL);

  loaded_image = gimp_file_load(GIMP_FILE_LOAD_DIALOG(NULL), NULL, temp_file_path, "XCF", &error);
  g_assert(error == NULL);
  g_assert(loaded_image != NULL);

  g_object_unref(file);
  g_remove(temp_file_path);
  g_free(temp_file_path);
}

void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
